"""مولّد تلقائياً — مكتبة nltk_ext لـ APL.

توسعة حزمة nltk: أصنافها ودوالها وطرقها وثوابتها التي لا تغطّيها مكتبات APL الأخرى

كل الأسماء وُلّدت آلياً وتُرجمت من معرفات الحزم الحقيقية، وتُرجم إلى مسارات
Python كاملة. كل عنصر يشير إلى كائن Python حقيقي فريد لا تغطّيه مكتبة أخرى،
والأسماء فريدة عبر كل مكتبات APL ونواة اللغة.
"""

